<section class="form-section card" id="preferences"><div class="form-section-head"><span>05</span><div><h2><?= e($sectionTitle('preferences','Programme preferences')) ?></h2><p><?= e($sectionDescription('preferences','Select and rank the programmes you want considered for.')) ?></p></div></div><form method="post" action="<?= url('student/application/save') ?>"><?= csrf_field() ?><input type="hidden" name="section" value="preferences"><div class="preference-list"><?php foreach($programs as $index=>$program):?><label class="preference-card"><input type="checkbox" name="program_preferences[]" value="<?= e($program['cycle_program_id']) ?>" <?= checked(in_array((int)$program['cycle_program_id'],$selectedPrefs,true)) ?> <?= !$preferencesEditable?'disabled':'' ?>><span class="preference-rank"><?= $index+1 ?></span><span><b><?= e($program['name']) ?></b><small><?= e($program['code']) ?> · <?= e(rtrim(rtrim((string)$program['duration_years'],'0'),'.')) ?> years · <?= e($program['seat_capacity']) ?> configured seats</small></span><strong><?= money($program['application_fee']) ?></strong></label><?php endforeach?></div><p class="form-hint">One application fee covers all ranked choices in this admission cycle.</p><?php if($preferencesEditable):?><div class="form-actions wizard-actions"><button class="button button-outline" type="submit" name="continue_to" value="preferences">Save for later</button><button class="button button-primary" type="submit" name="continue_to" value="<?= e($afterPreferences) ?>">Save & next: <?= $customFields?'Additional information':'Documents' ?> →</button></div><?php endif?></form></section>
<?php if($customFields):?><section class="form-section card" id="custom"><div class="form-section-head"><span>+</span><div><h2>Additional information</h2><p>Fields configured for this admission cycle.</p></div></div><form method="post" action="<?= url('student/application/save') ?>"><?= csrf_field() ?><input type="hidden" name="section" value="custom"><div class="form-grid"><?php foreach($customFields as $field): $response=$customResponses[(int)$field['id']]??null;$value=$response?($response['value_json']!==null?json_decode($response['value_json'],true):$response['value_text']):$field['default_value'];$options=json_decode((string)$field['options_json'],true)?:[];?><label class="<?= in_array($field['field_type'],['textarea','checkbox','multiselect'],true)?'full':'' ?>"><span><?= e($field['label']) ?><?= $field['is_required']?' *':'' ?></span><?php if($field['field_type']==='textarea'):?><textarea name="custom[<?= e($field['id']) ?>]" <?= $field['is_required']?'required':'' ?> <?= (!$customEditable||!($field['is_editable']??true))?'disabled':'' ?>><?= e($value) ?></textarea><?php elseif($field['field_type']==='select'):?><select name="custom[<?= e($field['id']) ?>]" <?= $field['is_required']?'required':'' ?> <?= (!$customEditable||!($field['is_editable']??true))?'disabled':'' ?>><option value="">Select</option><?php foreach($options as $optionValue=>$optionLabel): if(is_int($optionValue))$optionValue=$optionLabel;?><option value="<?= e($optionValue) ?>"<?= selected($value,$optionValue) ?>><?= e($optionLabel) ?></option><?php endforeach?></select><?php elseif($field['field_type']==='radio'): foreach($options as $optionValue=>$optionLabel): if(is_int($optionValue))$optionValue=$optionLabel;?><span class="check-control"><input type="radio" name="custom[<?= e($field['id']) ?>]" value="<?= e($optionValue) ?>" <?= checked((string)$value===(string)$optionValue) ?> <?= $field['is_required']?'required':'' ?> <?= (!$customEditable||!($field['is_editable']??true))?'disabled':'' ?>><?= e($optionLabel) ?></span><?php endforeach; elseif($field['field_type']==='checkbox'): foreach($options as $optionValue=>$optionLabel): if(is_int($optionValue))$optionValue=$optionLabel;?><span class="check-control"><input type="checkbox" name="custom[<?= e($field['id']) ?>][]" value="<?= e($optionValue) ?>" <?= checked(in_array((string)$optionValue,(array)$value,true)) ?> <?= (!$customEditable||!($field['is_editable']??true))?'disabled':'' ?>><?= e($optionLabel) ?></span><?php endforeach; elseif($field['field_type']==='multiselect'):?><select name="custom[<?= e($field['id']) ?>][]" multiple <?= $field['is_required']?'required':'' ?> <?= (!$customEditable||!($field['is_editable']??true))?'disabled':'' ?>><?php foreach($options as $optionValue=>$optionLabel): if(is_int($optionValue))$optionValue=$optionLabel;?><option value="<?= e($optionValue) ?>"<?= in_array((string)$optionValue,(array)$value,true)?' selected':'' ?>><?= e($optionLabel) ?></option><?php endforeach?></select><?php elseif($field['field_type']==='file'):?><small>Use the protected document section below for this configured file requirement.</small><?php else:?><input type="<?= e(in_array($field['field_type'],['email','number','date','tel'],true)?$field['field_type']:'text') ?>" name="custom[<?= e($field['id']) ?>]" value="<?= e($value) ?>" placeholder="<?= e($field['placeholder']) ?>" <?= $field['is_required']?'required':'' ?> <?= (!$customEditable||!($field['is_editable']??true))?'disabled':'' ?>><?php endif?><?php if($field['help_text']):?><small><?= e($field['help_text']) ?></small><?php endif?></label><?php endforeach?></div><?php if($customEditable):?><div class="form-actions wizard-actions"><button class="button button-outline" type="submit" name="continue_to" value="custom">Save for later</button><button class="button button-primary" type="submit" name="continue_to" value="documents">Save & next: Documents →</button></div><?php endif?></form></section><?php endif?>
<section class="form-section card" id="documents"><div class="form-section-head"><span>06</span><div><h2>Documents</h2><p>Upload clear files. Private documents are served only after permission checks.</p></div></div><div class="upload-list"><?php foreach($requirements as $requirement): $uploaded=$docMap[$requirement['document_type_id']]??null;$docCanEdit=$application['status']==='draft'||in_array((string)$requirement['code'],array_map('strval',$correctionDocuments),true)||in_array((string)$requirement['document_type_id'],array_map('strval',$correctionDocuments),true);?><article><div class="upload-icon">▤</div><div class="upload-copy" data-upload-copy><b><?= e($requirement['name']) ?> <?= $requirement['is_required']?'<em>Required</em>':'' ?></b><small><?= e($requirement['description']) ?> · <?= e(ucfirst($requirement['stage'])) ?> stage</small><?php if($uploaded):?><span class="upload-status status-<?= e($uploaded['status']) ?>" data-upload-state><?= e(ucwords(str_replace('_',' ',$uploaded['status']))) ?> · <?= e($uploaded['original_name']) ?></span><a href="<?= url('files/document/'.$uploaded['id']) ?>" target="_blank" data-upload-view>View saved file</a><?php if($uploaded['review_remarks']):?><p><?= e($uploaded['review_remarks']) ?></p><?php endif?><?php endif?></div><?php if($docCanEdit):?><form method="post" action="<?= url('student/application/document') ?>" enctype="multipart/form-data" class="inline-upload auto-upload" data-auto-upload><?= csrf_field() ?><input type="hidden" name="document_type_id" value="<?= e($requirement['document_type_id']) ?>"><label><input type="file" name="document" accept=".pdf,.jpg,.jpeg,.png" required data-auto-upload-input><span data-file-picker-label><?= $uploaded?'Replace file':'Choose file' ?></span></label><button type="submit" class="auto-upload-fallback">Upload</button><small class="auto-upload-message" data-auto-upload-message aria-live="polite"><?= $uploaded?'Saved · revision '.(int)$uploaded['revision_no']:'Select one file to save it automatically' ?></small></form><?php endif?></article><?php endforeach?></div><div class="privacy-inline"><span>i</span><p>PDF, JPG or PNG · maximum 5 MB each. Filenames are replaced with random storage keys and each file receives a SHA-256 integrity checksum.</p></div><?php if($documentsEditable):?><form class="form-actions wizard-actions document-next" method="post" action="<?= url('student/application/documents/continue') ?>"><?= csrf_field() ?><span>Files save as soon as you select them.</span><button class="button button-primary" type="submit" data-document-continue>Save & next: Review →</button></form><?php endif?></section>
<section class="form-section card review-section" id="review"><div class="form-section-head"><span>07</span><div><h2>Review & submit</h2><p>Submission locks your record unless the college requests a correction.</p></div></div><div class="review-summary"><div><i>✓</i><span><b>Personal and contact details</b><small>Review sections 1–3 for accuracy</small></span></div><div><i>✓</i><span><b>Academic records and preferences</b><small>Values will be checked against uploaded evidence</small></span></div><div><i>✓</i><span><b>Required document uploads</b><small>The system validates these again on submission</small></span></div></div><?php if($editable):?><form method="post" action="<?= url('student/application/submit') ?>"><?= csrf_field() ?><?php if($application['status']==='draft'):?><label class="declaration"><input type="checkbox" name="declaration" value="1" required><span><b>Applicant declaration</b><?= e($application['declaration_text']??'I declare that the information and documents submitted are complete and correct to the best of my knowledge.') ?></span></label><?php endif?><button class="button button-gold button-block submit-application" type="submit" data-confirm="<?= $application['status']==='correction_required'?'Resubmit the requested corrections?':'Submit this application? You will not be able to edit it unless a correction is requested.' ?>"><?= $application['status']==='correction_required'?'Resubmit corrections':'Submit final application' ?> →</button></form><?php else:?><div class="submitted-note"><span>✓</span><div><b>Application submitted</b><p>Submitted on <?= format_date($application['submitted_at'],true) ?>. Track all further changes from your dashboard.</p></div></div><?php endif?></section></div></div>
